fun dazzColorScheme(
    family: DazzThemeFamily = DazzThemeFamily.Studio,
    darkTheme: Boolean = false,
): ColorScheme = when (family) {
    DazzThemeFamily.Studio -> if (darkTheme) DazzColorSchemes.StudioDark else DazzColorSchemes.StudioLight
    DazzThemeFamily.Bright -> if (darkTheme) DazzColorSchemes.BrightDark else DazzColorSchemes.BrightLight
    DazzThemeFamily.Frost -> if (darkTheme) DazzColorSchemes.FrostDark else DazzColorSchemes.FrostLight
    DazzThemeFamily.Graphite -> if (darkTheme) DazzColorSchemes.GraphiteDark else DazzColorSchemes.GraphiteLight
    DazzThemeFamily.Ember -> if (darkTheme) DazzColorSchemes.EmberDark else DazzColorSchemes.EmberLight
    DazzThemeFamily.Nocturne -> if (darkTheme) DazzColorSchemes.NocturneDark else DazzColorSchemes.NocturneLight
}
